  const audience = brief?.answers.audience || "the intended reader";
  const goal = brief?.answers.goal || "the central goal";
  const tone = brief?.answers.tone || "the target tone";
  const judgeMean =
    judges.length > 0
      ? Math.round(
          (judges.reduce((s, j) => s + j.score, 0) / judges.length) * 10,
        ) / 10
      : 0;

